def withdrawn_to_closed(apps, schema_editor):
    """Close deal replaced Withdraw: old Withdrawn deals become Closed, with the reason recorded."""
    Registration = apps.get_model("registrations", "Registration")
    Registration.objects.filter(status="withdrawn").update(
        status="closed", close_reason="withdrawn"
    )
    for name in ("RegistrationNotification", "NotificationEventSetting"):
        apps.get_model("registrations", name).objects.filter(
            event_type="registration_withdrawn"
        ).update(event_type="registration_closed")


def closed_to_withdrawn(apps, schema_editor):
    Registration = apps.get_model("registrations", "Registration")
    Registration.objects.filter(status="closed").update(status="withdrawn", close_reason="")
    for name in ("RegistrationNotification", "NotificationEventSetting"):
        apps.get_model("registrations", name).objects.filter(
            event_type="registration_closed"
        ).update(event_type="registration_withdrawn")


